import random
from sklearn.metrics import cohen_kappa_score

def majority(labels):
    return max(set(labels), key=labels.count)

def cohen_kappa(a, b):
    return float(cohen_kappa_score(a, b))

def bootstrap_kappa_ci(raters, pred, items, n=400, seed=7):
    rng = random.Random(seed)
    vals = []
    idx = list(items)
    for _ in range(n):
        samp = [rng.choice(idx) for _ in idx]
        ks = [cohen_kappa([raters[i][k] for i in samp], [pred[items.index(i)] for i in samp]) for k in range(3)]
        vals.append(sum(ks)/3)
    vals.sort()
    return vals[int(0.025*n)], vals[int(0.975*n)]

